class Solution:
    def numTriplets(self, nums1: List[int], nums2: List[int]) -> int:
        def count(a, b):
            res = 0
            for x in a:
                sq = x * x
                for j in range(len(b)):
                    for k in range(j + 1, len(b)):
                        if b[j] * b[k] == sq:
                            res += 1
            return res
        return count(nums1, nums2) + count(nums2, nums1)

