class Solution {
public:
    int numTriplets(vector<int>& nums1, vector<int>& nums2) {
        auto count = [](vector<int>& a, vector<int>& b) {
            long long res = 0;
            for (long long x : a) {
                long long sq = x * x;
                for (int j = 0; j < (int)b.size(); j++)
                    for (int k = j + 1; k < (int)b.size(); k++)
                        if ((long long)b[j] * b[k] == sq) res++;
            }
            return res;
        };
        return (int)(count(nums1, nums2) + count(nums2, nums1));
    }
};

